import logging
from .named_factory import Factory, NamedComponentFactory
from taf.collectors.core.entities.collector_group import CollectorGroup, StartableCollectorGroup, AsyncCollectorGroup
from taf.collectors.core.entities.startable import StartableComponent
from taf.collectors.core.entities.collectable import CollectableComponent
from taf.collectors.core.entities.async_collectable import AsyncCollectableComponent

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CollectorGroupFactory(NamedComponentFactory):
    _product_class = CollectorGroup


class StartableCollectorGroupFactory(CollectorGroupFactory):
    _product_class = StartableCollectorGroup


class AsyncCollectorGroupFactory(NamedComponentFactory):
    _product_class = AsyncCollectorGroup


class CollectorGroupFactorySelector(Factory):

    def create(self, configuration, existing_arguments):
        if all(all(hasattr(member, meth) for meth in dir(StartableComponent) if not meth.startswith("_"))
               for member in existing_arguments["members"]):
            return StartableCollectorGroupFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        elif all(all(hasattr(member, meth) for meth in dir(CollectableComponent) if not meth.startswith("_"))
                 for member in existing_arguments["members"]):
            return CollectorGroupFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        elif all(all(hasattr(member, meth) for meth in dir(AsyncCollectableComponent) if not meth.startswith("_"))
                 for member in existing_arguments["members"]):
            return AsyncCollectorGroupFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        else:
            raise AssertionError(
                "Not all group members have the same type of API (start/stop, collect, async_collect): {members}".
                format(members=existing_arguments["members"]))
